values = iter([10, 20, 30])
for value in values:
    print(value)

class Count:
    def __init__(self, limit):
        self.current = 1
        self.limit = limit

    def __iter__(self):
        return self

    def __next__(self):
        if self.current > self.limit:
            raise StopIteration
        value = self.current
        self.current += 1
        return value

print(list(Count(3)))

