def announce(func):
    def wrapper():
        print("Before")
        func()
    return wrapper

@announce
def hello():
    print("Hello")

hello()

def upper(func):
    def wrapper():
        return func().upper()
    return wrapper

@upper
def message():
    return "hello"

print(message())

